              ref={inputRef}
              id="avatar-input"
              type="file"
              accept="image/png,image/jpeg,image/gif,image/webp"
              className="sr-only"
              onChange={handleFile}
              aria-labelledby="avatar-label"
              aria-describedby={error ? errorId : "avatar-hint"}
              tabIndex={-1}
            />
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => inputRef.current?.click()}
