    setSaving(true);
    window.setTimeout(() => {
      setSaving(false);
      setSaved(form);
      setSavedAvatar(avatarUrl);
      toast.success("Profile updated", {
        description: "Your changes are now visible to your team.",
      });
    }, 900);
  }

  function handleReset() {
    setForm(saved);
    setAvatarUrl(savedAvatar);
    setErrors({});
  }

  const bioLeft = MAX_BIO - form.bio.length;

  return (
