function DangerZone() {
  const [confirmText, setConfirmText] = React.useState("");
  const [open, setOpen] = React.useState(false);
  const [deleting, setDeleting] = React.useState(false);
  const [exporting, setExporting] = React.useState(false);

  const canDelete = confirmText.trim() === "delete my account";

  function handleOpenChange(next: boolean) {
    if (deleting) return;
    setOpen(next);
    if (!next) setConfirmText("");
  }

  function handleDelete(event: React.MouseEvent<HTMLButtonElement>) {
    event.preventDefault();
    if (!canDelete) return;
    setDeleting(true);
    window.setTimeout(() => {
      setDeleting(false);
      setOpen(false);
      setConfirmText("");
      toast.success("Account scheduled for deletion", {
        description:
          "You have 14 days to change your mind. We've emailed you the details.",
      });
    }, 1200);
  }

  function handleExport() {
    setExporting(true);
    window.setTimeout(() => {
      setExporting(false);
      toast.success("Export requested", {
        description: `We'll email a download link to ${ACCOUNT_EMAIL} within a few minutes.`,
      });
    }, 900);
  }

  return (
    <Card className="border-destructive/40">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-destructive">
          <TriangleAlertIcon aria-hidden="true" className="size-5" />
          Danger zone
        </CardTitle>
        <CardDescription>
          These actions affect your whole account and are difficult or
          impossible to undo.
        </CardDescription>
      </CardHeader>
      <CardContent className="flex flex-col gap-0">
        <div className="flex flex-col gap-3 py-4 sm:flex-row sm:items-center sm:justify-between sm:gap-6">
          <div className="flex flex-col gap-1">
            <h3 className="text-sm font-medium">Export your data</h3>
            <p className="text-sm text-muted-foreground">
              Download a copy of your projects, comments and profile as a ZIP
              archive.
            </p>
          </div>
          <Button
            type="button"
            variant="outline"
            onClick={handleExport}
            disabled={exporting}
            className="shrink-0"
          >
            {exporting ? <Spinner data-icon="inline-start" /> : null}
            {exporting ? "Requesting…" : "Request export"}
          </Button>
        </div>
        <Separator />
        <div className="flex flex-col gap-3 py-4 sm:flex-row sm:items-center sm:justify-between sm:gap-6">
          <div className="flex flex-col gap-1">
            <h3 className="text-sm font-medium">Delete account</h3>
            <p className="text-sm text-muted-foreground">
              Permanently remove your account, 14 projects and 3 workspace
              memberships. This can&apos;t be undone after 14 days.
            </p>
          </div>

          <AlertDialog open={open} onOpenChange={handleOpenChange}>
            <AlertDialogTrigger asChild>
              <Button variant="destructive" className="shrink-0">
                <Trash2Icon data-icon="inline-start" />
                Delete account
              </Button>
            </AlertDialogTrigger>
            <AlertDialogContent>
              <AlertDialogHeader>
                <AlertDialogTitle>Delete your account?</AlertDialogTitle>
                <AlertDialogDescription>
                  This will permanently delete{" "}
                  <strong className="font-medium text-foreground">
                    {ACCOUNT_EMAIL}
                  </strong>{" "}
                  along with all of your projects and files after a 14-day
                  grace period.
                </AlertDialogDescription>
              </AlertDialogHeader>
              <Field>
                <FieldLabel htmlFor="confirm-delete">
                  Type{" "}
                  <span className="font-mono text-foreground">
                    delete my account
                  </span>{" "}
                  to confirm
                </FieldLabel>
                <Input
                  id="confirm-delete"
                  autoComplete="off"
                  value={confirmText}
                  onChange={(e) => setConfirmText(e.target.value)}
                  placeholder="delete my account"
                />
              </Field>
              <AlertDialogFooter>
                <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
                <Button
                  type="button"
                  variant="destructive"
                  disabled={!canDelete || deleting}
                  onClick={handleDelete}
                >
                  {deleting ? <Spinner data-icon="inline-start" /> : null}
                  {deleting ? "Deleting…" : "Delete account"}
                </Button>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        </div>
      </CardContent>
    </Card>
  );
}

